INSERT INTO finale_defs (episode, flat, patch, story_text) VALUES (1, 'FLOOR4_8', 'CREDIT', 'Once you beat the big badasses and' || CHR(10) || 'clean out the moon base you''re supposed' || CHR(10) || 'to win, aren''t you? Aren''t you? Where''s' || CHR(10) || 'your fat reward and ticket home? What' || CHR(10) || 'the hell is this? It''s not supposed to' || CHR(10) || 'end this way!' || CHR(10) || '' || CHR(10) || 'It stinks like rotten meat, but looks' || CHR(10) || 'like the lost Deimos base.  Looks like' || CHR(10) || 'you''re stuck on The Shores of Hell.' || CHR(10) || 'The only way out is through.' || CHR(10) || '' || CHR(10) || 'To continue the DOOM experience, play' || CHR(10) || 'The Shores of Hell and its amazing' || CHR(10) || 'sequel, Inferno!' || CHR(10) || '');
INSERT INTO finale_defs (episode, flat, patch, story_text) VALUES (2, 'SFLR6_1', 'VICTORY2', 'You''ve done it! The hideous cyber-' || CHR(10) || 'demon lord that ruled the lost Deimos' || CHR(10) || 'moon base has been slain and you' || CHR(10) || 'are triumphant! But ... where are' || CHR(10) || 'you? You clamber to the edge of the' || CHR(10) || 'moon and look down to see the awful' || CHR(10) || 'truth.' || CHR(10) || '' || CHR(10) || 'Deimos floats above Hell itself!' || CHR(10) || 'You''ve never heard of anyone escaping' || CHR(10) || 'from Hell, but you''ll make the bastards' || CHR(10) || 'sorry they ever heard of you! Quickly,' || CHR(10) || 'you rappel down to  the surface of' || CHR(10) || 'Hell.' || CHR(10) || '' || CHR(10) || 'Now, it''s on to the final chapter of' || CHR(10) || 'DOOM! -- Hell on Earth.');
INSERT INTO finale_defs (episode, flat, patch, story_text) VALUES (3, 'MFLR8_4', 'PFUB1', 'The loathsome spiderdemon that' || CHR(10) || 'masterminded the invasion of the moon' || CHR(10) || 'bases and caused so much death has had' || CHR(10) || 'its ass kicked for all time.' || CHR(10) || '' || CHR(10) || 'A hidden doorway opens and you enter.' || CHR(10) || 'You''ve proven too tough for Hell to' || CHR(10) || 'contain, and now Hell at last plays' || CHR(10) || 'fair -- for you emerge from the door' || CHR(10) || 'to see the green fields of Earth!' || CHR(10) || 'Home at last.' || CHR(10) || '' || CHR(10) || 'You wonder what''s been happening on' || CHR(10) || 'Earth while you were battling evil' || CHR(10) || 'unleashed. It''s good that no Hell-' || CHR(10) || 'spawn could have come through that' || CHR(10) || 'door with you ...');
INSERT INTO finale_defs (episode, flat, patch, story_text) VALUES (4, 'MFLR8_3', 'ENDPIC', 'the spider mastermind must have sent forth' || CHR(10) || 'its legions of hellspawn before your' || CHR(10) || 'final confrontation with that terrible' || CHR(10) || 'beast from hell.  but you stepped forward' || CHR(10) || 'and brought forth eternal damnation and' || CHR(10) || 'suffering upon the horde as a true hero' || CHR(10) || 'would in the face of something so evil.' || CHR(10) || '' || CHR(10) || 'besides, someone was gonna pay for what' || CHR(10) || 'happened to daisy, your pet rabbit.' || CHR(10) || '' || CHR(10) || 'but now, you see spread before you more' || CHR(10) || 'potential pain and gibbitude as a nation' || CHR(10) || 'of demons run amok among our cities.' || CHR(10) || '' || CHR(10) || 'next stop, hell on earth!');
